/**
 * Reel Vault fulfilment Worker
 * Cloudflare Worker + Razorpay Payment Link webhook + Resend
 * Secrets: RAZORPAY_WEBHOOK_SECRET, RESEND_API_KEY, DRIVE_LINK
 * Vars: FROM_EMAIL, PRODUCT_NAME, EXPECTED_AMOUNT_PAISE, RAZORPAY_PAYMENT_LINK_ID
 * KV binding: FULFILLED
 */
const json=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{"content-type":"application/json; charset=utf-8"}});
function timingSafeEqual(a,b){if(a.length!==b.length)return false;let mismatch=0;for(let i=0;i<a.length;i++)mismatch|=a.charCodeAt(i)^b.charCodeAt(i);return mismatch===0}
async function hmacHex(secret,payload){const enc=new TextEncoder();const key=await crypto.subtle.importKey("raw",enc.encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);const sig=await crypto.subtle.sign("HMAC",key,enc.encode(payload));return [...new Uint8Array(sig)].map(b=>b.toString(16).padStart(2,"0")).join("")}
function escapeHtml(value=""){return String(value).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}
async function sendDeliveryEmail(env,to,paymentId){const productName=env.PRODUCT_NAME||"Creator Reel Vault 2026";const response=await fetch("https://api.resend.com/emails",{method:"POST",headers:{authorization:`Bearer ${env.RESEND_API_KEY}`,"content-type":"application/json"},body:JSON.stringify({from:env.FROM_EMAIL,to:[to],subject:`Your ${productName} access`,html:`<div style="font-family:Arial,sans-serif;padding:24px"><h2>Payment verified</h2><p>Your ${escapeHtml(productName)} access is ready.</p><p><a href="${escapeHtml(env.DRIVE_LINK)}" style="display:inline-block;background:#111;color:#fff;padding:14px 18px;border-radius:9px;text-decoration:none;font-weight:700">Open Google Drive access</a></p><p style="color:#777;font-size:12px">Payment ID: ${escapeHtml(paymentId)}</p></div>`,text:`Payment verified.\n\nYour ${productName} access:\n${env.DRIVE_LINK}\n\nPayment ID: ${paymentId}`})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(`Resend failed (${response.status})`);return data}
export default{async fetch(request,env){const url=new URL(request.url);if(request.method==="GET"&&url.pathname==="/health")return json({ok:true,service:"reel-vault-fulfilment"});if(request.method!=="POST"||url.pathname!=="/razorpay-webhook")return json({error:"Not found"},404);const signature=request.headers.get("x-razorpay-signature");if(!signature)return json({error:"Missing signature"},400);const rawBody=await request.text();const expectedSignature=await hmacHex(env.RAZORPAY_WEBHOOK_SECRET,rawBody);if(!timingSafeEqual(signature,expectedSignature))return json({error:"Invalid signature"},401);let event;try{event=JSON.parse(rawBody)}catch{return json({error:"Invalid JSON"},400)}if(event.event!=="payment_link.paid")return json({ok:true,ignored:event.event||"unknown"});const payment=event?.payload?.payment?.entity;const paymentLink=event?.payload?.payment_link?.entity;if(!payment?.id||!paymentLink?.id)return json({error:"Incomplete payment payload"},400);if(payment.status!=="captured"||payment.captured!==true||paymentLink.status!=="paid")return json({error:"Payment is not fully captured/paid"},409);const expectedAmount=Number(env.EXPECTED_AMOUNT_PAISE||"19900");if(Number(payment.amount)!==expectedAmount||Number(paymentLink.amount_paid)<expectedAmount||payment.currency!=="INR"||paymentLink.currency!=="INR")return json({error:"Payment amount or currency mismatch"},409);if(env.RAZORPAY_PAYMENT_LINK_ID&&paymentLink.id!==env.RAZORPAY_PAYMENT_LINK_ID)return json({error:"Unexpected payment link"},409);const email=paymentLink?.customer?.email||payment?.email;if(!email)return json({error:"Buyer email missing from payment payload"},422);const dedupeKey=`payment:${payment.id}`;if(await env.FULFILLED.get(dedupeKey))return json({ok:true,duplicate:true});const emailResult=await sendDeliveryEmail(env,email,payment.id);await env.FULFILLED.put(dedupeKey,JSON.stringify({paymentId:payment.id,paymentLinkId:paymentLink.id,email,deliveredAt:new Date().toISOString(),resendId:emailResult?.id||null}),{expirationTtl:31536000});return json({ok:true})}};
